// GET /api/scheduler/due returns { posts: [...] } as ONE item (a JSON
// object, not a bare array) -- split it into one n8n item per due post so
// everything downstream runs once per post.
const posts = ($input.first().json && $input.first().json.posts) || [];
return posts.map((p) => ({ json: p }));

// Builds the final LinkedIn post text from whichever the Writing Agent
// produced: a single body (SINGLE_POST/ARTICLE) or per-slide bullets
// (CAROUSEL -- true multi-image carousel posting isn't attempted here, see
// the workflow doc's "CAROUSEL handling" note; slides are joined into one
// numbered text post instead).
return $input.all().map((item) => {
  const p = item.json;
  let text = p.content || "";

  if (!text && Array.isArray(p.slides) && p.slides.length > 0) {
    text = p.slides.map((s, i) => `${i + 1}. ${s}`).join("\n\n");
  }

  if (Array.isArray(p.hashtags) && p.hashtags.length > 0) {
    text += "\n\n" + p.hashtags.map((h) => `#${h}`).join(" ");
  }

  return {
    json: {
      ...p,
      postText: text,
      hasImage: Boolean(p.imageUrl)
    }
  };
});

// Both LinkedIn nodes converge here. `continueOnFail: true` on those nodes
// means a failed publish attempt still produces an item here (with an
// `error` field) instead of crashing the workflow -- this node decides
// success vs failure and builds the exact shape POST /api/scheduler/publish
// expects. `scheduledPostId` is recovered via pairedItem back to "Build Post
// Text" rather than assumed to survive through the LinkedIn node, since
// action nodes commonly replace `.json` with the raw API response.
//
// NOTE: `item.json.id` is this workflow's one live-unverified assumption --
// confirm the actual field holding the created post's identifier by
// inspecting a real successful execution's output in your n8n instance, and
// adjust the fallbacks below if it differs (see the workflow doc).
const originItems = $('Build Post Text').all();

return $input.all().map((item) => {
  const originIdx = item.pairedItem ? item.pairedItem.item : undefined;
  const original = originIdx !== undefined ? originItems[originIdx].json : {};
  const scheduledPostId = original.scheduledPostId;

  const hasError = Boolean(item.json.error) || Boolean(item.json.errorMessage);
  if (hasError) {
    const errorMessage =
      (item.json.error && (item.json.error.message || String(item.json.error))) ||
      item.json.errorMessage ||
      "Unknown LinkedIn publish error";
    return { json: { scheduledPostId, success: false, error: errorMessage } };
  }

  const postId = item.json.id || item.json.postId || item.json.urn || null;
  const publishedUrl = postId ? `https://www.linkedin.com/feed/update/${postId}` : undefined;

  return { json: { scheduledPostId, success: true, publishedUrl } };
});
